#include <iostream>
#include <vector>
#include <string>
#include <algorithm>
using namespace std;

vector<int> parent;

int findRoot(int x) {
    int root = x;
    while (parent[root] != root) root = parent[root];
    while (parent[x] != root) {
        int next = parent[x];
        parent[x] = root;
        x = next;
    }
    return root;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long n;
    cin >> n;
    vector<vector<long long>> jobs(n, vector<long long>(2));
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < 2; j++) {
            cin >> jobs[i][j];
        }
    }

    parent.resize(n + 1);
    for (int v = 0; v <= n; v++) parent[v] = v;
    vector<int> order(n);
    for (int i = 0; i < n; i++) order[i] = i;
    sort(order.begin(), order.end(), [&](int x, int y) { return jobs[x][1] > jobs[y][1]; });
    long long total = 0;
    for (int i : order) {
        int slot = findRoot((int)min(jobs[i][0], n));
        if (slot > 0) {
            total += jobs[i][1];
            parent[slot] = slot - 1;
        }
    }
    cout << total << "\n";

    return 0;
}

