import java.io.*;
import java.util.*;

public class Main {
    static BufferedReader in = new BufferedReader(new InputStreamReader(System.in));
    static StringTokenizer tokens = new StringTokenizer("");

    static String next() throws IOException {
        while (!tokens.hasMoreTokens()) {
            tokens = new StringTokenizer(in.readLine());
        }
        return tokens.nextToken();
    }

    static int[] parent;

    static int findRoot(int x) {
        int root = x;
        while (parent[root] != root) root = parent[root];
        while (parent[x] != root) {
            int next = parent[x];
            parent[x] = root;
            x = next;
        }
        return root;
    }

    public static void main(String[] args) throws IOException {
        long n = Long.parseLong(next());
        long[][] jobs = new long[(int) n][2];
        for (int i = 0; i < jobs.length; i++) {
            for (int j = 0; j < jobs[i].length; j++) {
                jobs[i][j] = Long.parseLong(next());
            }
        }

        int count = (int) n;
        long[] keys = new long[count];
        for (int i = 0; i < count; i++) keys[i] = jobs[i][1] * 65536L + i;
        Arrays.sort(keys);
        parent = new int[count + 1];
        for (int v = 0; v <= count; v++) parent[v] = v;
        long total = 0;
        for (int t = count - 1; t >= 0; t--) {
            int i = (int) (keys[t] % 65536L);
            int slot = findRoot((int) Math.min(jobs[i][0], (long) count));
            if (slot > 0) {
                total += jobs[i][1];
                parent[slot] = slot - 1;
            }
        }
        System.out.println(total);
    }
}
